    /**
     * Collapse behavior.
     * @defaultValue 'icon'
     */
    collapsible?: 'offcanvas' | 'icon' | 'none';
    /**
     * Whether the panel renders as a floating overlay.
     * @defaultValue false
     */
    overlay?: boolean;
    /**
     * Controlled open state. Use with `v-model:open` or `@update:open`.
     */
    open?: boolean;
    /**
     * When true, hovering the panel triggers expand/collapse.
     * @defaultValue false
     */
